def compute(vars):
    v1 = vars["v1"]  # 2019
    v2 = vars["v2"]  # 2018
    value = v1 - v2
    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "difference": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
